{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C19"],
      "claim": "In healthy volunteers, verapamil absolute oral bioavailability was 27% after an 80 mg oral dose versus IV, above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C73"],
      "claim": "Tramadol absolute oral bioavailability in humans after single oral doses is 70% of IV exposure, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C72"],
      "claim": "Levosulpiride absolute oral bioavailability was 23.4% in Chinese volunteers after a 50 mg oral dose versus IV, still above the 20% threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "All ten evidence molecules have numeric absolute oral bioavailability values at or above 20% in humans; the lowest robust values (levosulpiride 23.4%, verapamil 27%) remain above threshold, so the query is predicted high.",
  "evidence_gaps": [
    "Some verapamil records report F below 20% (12-19.25%), but the strongest absolute human measurement is 27%; this introduces minor threshold-proximity uncertainty.",
    "Record C58 under pethidine appears to describe morphine rather than pethidine and was discounted as a provenance conflict.",
    "Several records use unspecified bioavailability type or qualitative 'low' language; numeric absolute measurements were prioritized."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

